リポジトリのファイルを確認して、タスクを実装します。

タスクは：Vok が 'pex' の状態から直接 'dor' へ進む高速 operation 'advanceVokSkip' を追加すること。

まず、現在のファイル構造を分析します：

1. `src/protocol_adapter.ts` - プロトコルの主要なインターフェース
2. `src/vok/rules.ts` - Vok のルールとロジック

現在のコードを確認して、`advanceVokSkip` operation を実装する必要があります。

<modified_files>
{
  "src/vok/rules.ts": "import { WorldProtocol } from '../protocol_adapter';

export interface VokState {
  state: 'pex' | 'dor' | 'voy';
  energy: number;
}

export const createVokRules = () => {
  return {
    advanceVok: (vokState: VokState): VokState => {
      if (vokState.state === 'pex') {
        return { ...vokState, state: 'dor', energy: vokState.energy - 1 };
      }
      if (vokState.state === 'dor') {
        return { ...vokState, state: 'voy', energy: vokState.energy - 1 };
      }
      return vokState;
    },
    advanceVokSkip: (vokState: VokState): VokState => {
      if (vokState.state === 'pex') {
        return { ...vokState, state: 'dor', energy: vokState.energy };
      }
      return vokState;
    },
  };
};
",
  "src/protocol_adapter.ts": "import { createVokRules } from './vok/rules';

export interface WorldProtocol {
  reset(): void;
  applyOperation(operationName: string, payload?: any): void;
  getEntityState(entityId: string): any;
  toAbstractSnapshot(): any;
}

const vokRules = createVokRules();

const entities: Map<string, any> = new Map();

export const protocol: WorldProtocol = {
  reset(): void {
    entities.clear();
  },

  applyOperation(operationName: string, payload?: any): void {
    if (operationName === 'advanceVok') {
      const entity = entities.get('vok') || { state: 'pex', energy: 10 };
      entities.set('vok', vokRules.advanceVok(entity));
    } else if (operationName === 'advanceVokSkip') {
      const entity = entities.get('vok') || { state: 'pex', energy: 10 };
      entities.set('vok', vokRules.advanceVokSkip(entity));
    }
  },

  getEntityState(entityId: string): any {
    return entities.get(entityId);
  },

  toAbstractSnapshot(): any {
    const snapshot: any = {};
    entities.forEach((value, key) => {
      snapshot[key] = value;
    });
    return snapshot;
  },
};
"
